      closed[cur] = 1;

      const ix = cur % NX;
      const iy = (cur - ix) / NX;
      const cg = gScore[cur];

      for (let d = 0; d < 8; d++) {
        const dx = dirs[d][0];
        const dy = dirs[d][1];
        const step = dirs[d][2];
        const nix = ix + dx;
        const niy = iy + dy;
        if (nix < 0 || nix >= NX || niy < 0 || niy >= NY) continue;
        if (blockedCell(nix, niy)) continue;
        if (dx !== 0 && dy !== 0) {
          if (blockedCell(ix + dx, iy) || blockedCell(ix, iy + dy)) continue;
        }
        const ni = niy * NX + nix;
        if (closed[ni]) continue;
        const ng = cg + step;
        if (ng + 1e-7 < gScore[ni]) {
          gScore[ni] = ng;
          parent[ni] = cur;
          const hh = heur(nix, niy);
          if (hh < bestH) {
