    let rc = Math.min(rays[1], 6) + 0.55 * Math.min(rays[0], 6);
    let dir;
    if (lc > rc + 0.05) dir = 1;
    else if (rc > lc + 0.05) dir = -1;
    else dir = e >= 0 ? 1 : -1;

    mem.recoverDir = dir;
    mem.recoverUntil = t + 0.85;
    mem.stuckCount = 0;
    mem.path = [];
    mem.nextPlan = 0;
  }

  if (t < mem.recoverUntil) {
    const tt = 0.32 * (mem.recoverDir || 1);
    let l = -tt;
    let r = tt;
    l = clamp(l, -1, 1);
    r = clamp(r, -1, 1);
    if (Math.abs(l) < 0.04) l = 0;
    if (Math.abs(r) < 0.04) r = 0;
