    const rc = Math.min(rays[1], 5) + 0.55 * Math.min(rays[0], 5);
    let pref;
    if (lc > rc + 0.05) pref = 1;
    else if (rc > lc + 0.05) pref = -1;
    else pref = e >= 0 ? 1 : -1;
