  avoid = clamp(avoid, -0.75, 0.75);

  const eCtrl = wrap(e + avoid);
  const absE = Math.abs(eCtrl);

  if (rays[2] > 0.85 && Math.abs(e) < 0.55 && Math.abs(mem.turn) < 0.25) {
