  if (distT < 1.35) v = Math.min(v, 0.24);
  if (distT < 0.85) v = Math.min(v, 0.10);

  const speedAbs = Math.max(0, speed);
  const brake =
    (speedAbs > 0.28 &&
      (ahead < 0.62 + speedAbs * 0.62 ||
       minSide < 0.20 + speedAbs * 0.16)) ||
    (speedAbs > 0.62 && (front < 1.30 || minSide < 0.36)) ||
    (speedAbs > 0.82 && minSide < 0.45 + speedAbs * 0.75) ||
    (speedAbs > 1.05 && ahead < 1.55 + speedAbs * 0.25);

  if (brake) {
    let br = 0;
    if (minSide < 1.00) {
      br = clamp((lClear - rClear) * 0.07, -0.06, 0.06);
      if (Math.abs(br) < 0.015) br = 0;
    }
    mem.base = 0;
    mem.turn *= 0.70;
    return {
      left: clamp(-0.18 - br, -1, 1),
      right: clamp(-0.18 + br, -1, 1)
