    if (moved < 0.15 && distT > 1.10 && speed < 0.18 && front > 0.55) {
      mem.stuckCount++;
    } else {
      mem.stuckCount = 0;
    }
    mem.anchorT = t;
    mem.anchorX = x;
    mem.anchorY = y;

    if (mem.stuckCount >= 2 && minSide > 0.28 && front > 0.55) {
      mem.recoverUntil = t + 0.75;
      mem.recoverBackUntil = t + 0.30;
      mem.stuckCount = 0;
      if (lClear > rClear + 0.08) mem.recoverDir = 1;
      else if (rClear > lClear + 0.08) mem.recoverDir = -1;
      else mem.recoverDir = e >= 0 ? 1 : -1;
