  if (base < 0.055 && (Math.abs(turnCmd) > 0.02 || absE > 0.15)) {
    let p = Math.abs(turnCmd);
    if (p < 0.14) p = 0.14;
    p = Math.min(p, 0.22);
    if (minSide < 0.30) p = Math.min(p, 0.12);
