  R = clamp(R, mem.lastR - 0.2, mem.lastR + 0.2);
  if (Math.abs(L) < 0.03) L = 0;
  if (Math.abs(R) < 0.03) R = 0;
  mem.lastL = L; mem.lastR = R;
  return { left: L, right: R };
}

const D2R = Math.PI / 180;
const ANG = [-60, -30, 0, 30, 60]; // positive = left (CCW) of heading
const CELL = 0.5, N = 80, NN = N * N;
const BLOCK = 0.9;
const VMAX = 0.45;
const LOOK = 2.0;
const DI = [1, -1, 0, 0, 1, 1, -1, -1];
const DJ = [0, 0, 1, -1, 1, -1, 1, -1];

function wrap(a) { while (a > 180) a -= 360; while (a < -180) a += 360; return a; }
function clamp(v, a, b) { return Math.max(a, Math.min(b, v)); }
function num(v, d) { return (typeof v === 'number' && isFinite(v)) ? v : d; }
function cellOf(x, y) {
  const i = clamp(Math.floor(x / CELL), 0, N - 1);
  const j = clamp(Math.floor(y / CELL), 0, N - 1);
  return j * N + i;
}
function cx(c) { return ((c % N) + 0.5) * CELL; }
function cy(c) { return (Math.floor(c / N) + 0.5) * CELL; }

function heapPush(h, it) {
  h.push(it);
  let i = h.length - 1;
  while (i > 0) {
    const p = (i - 1) >> 1;
    if (h[p][0] <= h[i][0]) break;
    const t = h[p]; h[p] = h[i]; h[i] = t;
    i = p;
  }
}
function heapPop(h) {
  const top = h[0];
  const last = h.pop();
  if (h.length) {
    h[0] = last;
    let i = 0;
    for (;;) {
      const l = 2 * i + 1, r = l + 1;
      let m = i;
      if (l < h.length && h[l][0] < h[m][0]) m = l;
      if (r < h.length && h[r][0] < h[m][0]) m = r;
      if (m === i) break;
      const t = h[m]; h[m] = h[i]; h[i] = t;
      i = m;
    }
  }
  return top;
}

function freeCell(occ, c) { if (occ[c] < 4) occ[c] = Math.max(-2, occ[c] - 0.2); }

function updateMap(occ, x, y, h, rays) {
  freeCell(occ, cellOf(x, y));
  for (let k = 0; k < 5; k++) {
    const d = rays[k];
    const a = (h + ANG[k]) * D2R;
    const ca = Math.cos(a), sa = Math.sin(a);
    const top = Math.min(d, 9.5);
    for (let s = 0.25; s < top - 0.3; s += 0.25) freeCell(occ, cellOf(x + s * ca, y + s * sa));
    if (d < 9.5) {
      const c = cellOf(x + d * ca, y + d * sa);
      if (occ[c] < 4) occ[c] = Math.min(4, occ[c] + 0.5);
    }
  }
}

function decayMap(occ) {
  for (let c = 0; c < NN; c++) if (occ[c] > -2 && occ[c] < 4) occ[c] *= 0.6;
}

function lineClear(occ, x0, y0, x1, y1) {
  const d = Math.hypot(x1 - x0, y1 - y0);
  const n = Math.max(1, Math.ceil(d / 0.25));
  for (let k = 1; k < n; k++) {
    const t = k / n;
    if (occ[cellOf(x0 + (x1 - x0) * t, y0 + (y1 - y0) * t)] >= BLOCK) return false;
  }
  return true;
}

function pathBlocked(occ, path) {
  if (!path || path.length < 2) return false;
  const m = Math.min(8, path.length - 1);
  for (let k = 0; k < m; k++) if (occ[path[k]] >= BLOCK) return true;
  return false;
}

function plan(occ, s, g) {
  if (s === g) return [];
  const gS = new Float32Array(NN).fill(1e9);
  const came = new Int32Array(NN).fill(-1);
  const closed = new Uint8Array(NN);
  const gi = g % N, gj = Math.floor(g / N);
  const hf = (c) => {
    const i = c % N, j = Math.floor(c / N);
    const dx = Math.abs(i - gi), dy = Math.abs(j - gj);
    return Math.max(dx, dy) + 0.414 * Math.min(dx, dy);
  };
  const open = [];
  gS[s] = 0;
  heapPush(open, [hf(s), s]);
  while (open.length) {
    const top = heapPop(open);
    const c = top[1];
    if (closed[c]) continue;
    closed[c] = 1;
    if (c === g) break;
    const i = c % N, j = Math.floor(c / N);
    for (let m = 0; m < 8; m++) {
      const ni = i + DI[m], nj = j + DJ[m];
      if (ni < 0 || nj < 0 || ni >= N || nj >= N) continue;
      const n = nj * N + ni;
      if (closed[n]) continue;
      if (n !== g && occ[n] >= BLOCK) continue;
      const diag = m >= 4;
      if (diag && (occ[j * N + ni] >= BLOCK || occ[nj * N + i] >= BLOCK)) continue;
      let pen = 0;
      for (let q = 0; q < 4; q++) {
        const qi = ni + DI[q], qj = nj + DJ[q];
        if (qi < 0 || qj < 0 || qi >= N || qj >= N) continue;
        if (occ[qj * N + qi] >= BLOCK) pen += 0.7;
      }
      const step = diag ? 1.414 : 1;
      const ng = gS[c] + step + pen;
      if (ng < gS[n] - 1e-6) {
        gS[n] = ng;
        came[n] = c;
        heapPush(open, [ng + hf(n), n]);
      }
    }
  }
  if (!closed[g]) return null;
  const path = [];
  let c = g;
  while (c !== -1 && c !== s) { path.push(c); c = came[c]; }
  path.reverse();
  return path;
}

function init(mem) {
  mem.occ = new Float32Array(NN);
  for (let j = 0; j < N; j++) for (let i = 0; i < N; i++) {
    if (i === 0 || j === 0 || i === N - 1 || j === N - 1) mem.occ[j * N + i] = 5;
  }
  mem.off = 0; mem.gps = []; mem.hist = []; mem.path = null; mem.hf = undefined;
  mem.tick = 0; mem.nextPlan = 0; mem.lastTI = -1;
  mem.lastL = 0; mem.lastR = 0; mem.straight = 0;
  mem.mode = 0; mem.modeT = 0; mem.bdir = 1;
  mem.cool = 0; mem.fails = 0; mem.prevRays = null;
}

function act(obs, mem) {
  if (!mem.occ) init(mem);
  mem.tick++;

  const x = num(obs.x, 0), y = num(obs.y, 0);
  const hd = num(obs.heading, 0);
  const raw = [0, 1, 2, 3, 4].map(i => clamp(num(obs.rays ? obs.rays[i] : 10, 10), 0, 10));
  // two-tick minimum rejects single missed detections
  const rays = mem.prevRays ? raw.map((r, k) => Math.min(r, mem.prevRays[k])) : raw;
  mem.prevRays = raw;

  const tx = num(obs.targetX, x), ty = num(obs.targetY, y);
  const ti = num(obs.targetIndex, 0);
  const dT = Math.hypot(tx - x, ty - y);

  // ---- GPS course -> compass offset (only while driving straight forward) ----
  mem.gps.push({ x, y });
  if (mem.gps.length > 21) mem.gps.shift();
  const moving = mem.lastL > 0.2 && mem.lastR > 0.2 && Math.abs(mem.lastL - mem.lastR) < 0.12;
  mem.straight = moving ? mem.straight + 1 : 0;
  if (mem.gps.length === 21 && mem.straight >= 20) {
    const a = mem.gps[0], b = mem.gps[20];
    if (Math.hypot(b.x - a.x, b.y - a.y) > 0.5) {
      const course = Math.atan2(b.y - a.y, b.x - a.x) / D2R;
      mem.off = wrap(mem.off + 0.02 * wrap(course - (hd + mem.off)));
    }
  }

  // ---- heading: compass + offset, low-pass filtered ----
  const hc = hd + mem.off;
  if (mem.hf === undefined) mem.hf = wrap(hc);
  else mem.hf = wrap(mem.hf + 0.3 * wrap(hc - mem.hf));
  const h = mem.hf;

  updateMap(mem.occ, x, y, h, rays);

  // ---- planning ----
  if (ti !== mem.lastTI) { mem.lastTI = ti; mem.path = null; mem.nextPlan = 0; }
  if (mem.tick >= mem.nextPlan || pathBlocked(mem.occ, mem.path)) {
    const p = plan(mem.occ, cellOf(x, y), cellOf(tx, ty));
    mem.path = p;
    mem.nextPlan = mem.tick + 10;
    if (!p) {
      mem.fails++;
      if (mem.fails % 3 === 0) decayMap(mem.occ);
    } else mem.fails = 0;
  }
  const path = mem.path || [];
  while (path.length > 1 && Math.hypot(cx(path[0]) - x, cy(path[0]) - y) < 0.6) path.shift();

  // ---- waypoint: farthest clear path node within LOOK metres (pure pursuit) ----
  let wx = tx, wy = ty;
  if (!(dT < LOOK && lineClear(mem.occ, x, y, tx, ty)) && path.length) {
    let best = 0;
    for (let k = 0; k < path.length; k++) {
      const px = cx(path[k]), py = cy(path[k]);
      if (Math.hypot(px - x, py - y) > LOOK) break;
      if (lineClear(mem.occ, x, y, px, py)) best = k;
    }
    wx = cx(path[best]); wy = cy(path[best]);
  }

  // ---- steering: gentle proportional law (actuator lag means high gain oscillates) ----
  const tgtH = Math.atan2(wy - y, wx - x) / D2R;
  const e = wrap(tgtH - h);
  const ae = Math.abs(e);
  const front = rays[2];
  const openL = rays[3] + rays[4], openR = rays[0] + rays[1];

  // positive t = turn left (CCW): R faster than L
  let t = clamp(e / 220, -0.35, 0.35);
  // gentle side repulsion, only when something is close
  const cl = Math.max(0, 1.2 - rays[3]) + 0.5 * Math.max(0, 1.2 - rays[4]);
  const cr = Math.max(0, 1.2 - rays[1]) + 0.5 * Math.max(0, 1.2 - rays[0]);
  t += clamp(0.12 * (cr - cl), -0.15, 0.15);
  t = clamp(t, -0.4, 0.4);

  // forward speed: creep/stop when badly aligned or something ahead
  let v = VMAX * clamp((70 - ae) / 40, 0, 1);
  v *= clamp((front - 0.8) / 1.6, 0, 1);
  if (Math.min(rays[1], rays[3]) < 0.6) v *= 0.7;

  // ---- stuck detection (little translation over 3 s, little turning) ----
  mem.hist.push({ x, y, h });
  if (mem.hist.length > 60) mem.hist.shift();
  if (mem.cool > 0) mem.cool--;

  if (mem.mode === 0 && mem.cool === 0 && mem.hist.length >= 60 && dT > 1.5) {
    const a = mem.hist[0];
    const moved = Math.hypot(x - a.x, y - a.y);
    const turned = Math.abs(wrap(h - a.h));
    if (moved < 0.35 && turned < 45) {
      mem.bdir = openL >= openR ? 1 : -1;
      mem.mode = 1; mem.modeT = 20;
      mem.path = null; mem.nextPlan = 0;
      mem.hist = [];
      mem.cool = 40;
    }
  }

  let L = 0, R = 0;
  if (mem.mode === 1) {
    // committed reverse
    L = -0.3; R = -0.3;
    mem.modeT--;
    if (mem.modeT <= 0) { mem.mode = 2; mem.modeT = 24; }
  } else if (mem.mode === 2) {
    // committed pivot toward the more open side (bdir +1 = left)
    L = -0.35 * mem.bdir; R = 0.35 * mem.bdir;
    mem.modeT--;
    if (mem.modeT <= 0) { mem.mode = 0; mem.path = null; mem.nextPlan = 0; }
  } else {
    L = v - t;
    R = v + t;
  }

  L = clamp(L, -1, 1); R = clamp(R, -1, 1);
  // slew limit: motors lag
  L = clamp(L, mem.lastL - 0.12, mem.lastL + 0.12);
  R = clamp(R, mem.lastR - 0.12, mem.lastR + 0.12);
  if (Math.abs(L) < 0.03) L = 0;
  if (Math.abs(R) < 0.03) R = 0;
  mem.lastL = L; mem.lastR = R;
  return { left: L, right: R };
}
